// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceWhooshCore {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // This creates 1-element array, since this seems to be the only way to construct a const
    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceWhooshCore] = [UniffiVTableCallbackInterfaceWhooshCore(
        run: { (
            uniffiHandle: UInt64,
            command: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> CommandOutcome in
                guard let uniffiObj = try? FfiConverterTypeWhooshCore.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try uniffiObj.run(
                     command: try FfiConverterTypeCommand_lift(command)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterTypeCommandOutcome_lower($0) }
            uniffiTraitInterfaceCallWithError(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn,
                lowerError: FfiConverterTypeCoreError_lower
            )
        },
        inbox: { (
            uniffiHandle: UInt64,
            query: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> [InboxRow] in
                guard let uniffiObj = try? FfiConverterTypeWhooshCore.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.inbox(
                     query: try FfiConverterTypeInboxQuery_lift(query)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterSequenceTypeInboxRow.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        inboxRows: { (
            uniffiHandle: UInt64,
            query: RustBuffer,
            rows: UInt32,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> [InboxRow] in
                guard let uniffiObj = try? FfiConverterTypeWhooshCore.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.inboxRows(
                     query: try FfiConverterTypeInboxQuery_lift(query),
                     rows: try FfiConverterUInt32.lift(rows)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterSequenceTypeInboxRow.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        unsubscribeMethod: { (
            uniffiHandle: UInt64,
            messageId: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> UnsubscribeMethod? in
                guard let uniffiObj = try? FfiConverterTypeWhooshCore.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.unsubscribeMethod(
                     messageId: try FfiConverterString.lift(messageId)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterOptionTypeUnsubscribeMethod.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        attachments: { (
