    return FfiConverterTypeWhooshCore.lower(value)
}




public struct Account {
    public var id: String
    public var address: String
    public var provider: MailProvider
    public var displayName: String
    /**
     * "#RRGGBB"
     */
    public var colour: String
    public var order: UInt32
    public var paused: Bool
    /**
     * optional grouping: Work, Personal, Clients, Side
     */
    public var group: String?
    public var iconId: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, address: String, provider: MailProvider, displayName: String, 
        /**
         * "#RRGGBB"
         */colour: String, order: UInt32, paused: Bool, 
        /**
         * optional grouping: Work, Personal, Clients, Side
         */group: String?, iconId: String?) {
        self.id = id
        self.address = address
        self.provider = provider
        self.displayName = displayName
        self.colour = colour
        self.order = order
        self.paused = paused
        self.group = group
        self.iconId = iconId
    }
}

#if compiler(>=6)
extension Account: Sendable {}
#endif


extension Account: Equatable, Hashable {
    public static func ==(lhs: Account, rhs: Account) -> Bool {
        if lhs.id != rhs.id {
            return false
        }
        if lhs.address != rhs.address {
            return false
        }
        if lhs.provider != rhs.provider {
            return false
        }
        if lhs.displayName != rhs.displayName {
            return false
        }
        if lhs.colour != rhs.colour {
            return false
        }
        if lhs.order != rhs.order {
            return false
        }
        if lhs.paused != rhs.paused {
            return false
        }
        if lhs.group != rhs.group {
            return false
        }
        if lhs.iconId != rhs.iconId {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(id)
        hasher.combine(address)
        hasher.combine(provider)
        hasher.combine(displayName)
        hasher.combine(colour)
        hasher.combine(order)
        hasher.combine(paused)
        hasher.combine(group)
        hasher.combine(iconId)
    }
}



