/**
 * A complete server configuration: the account table's server columns (migration 0003).
 */
public struct AccountConfig {
    public var imapHost: String
    public var imapPort: UInt16
    public var imapSecurity: ConnectionSecurity
    public var smtpHost: String
    public var smtpPort: UInt16
    public var smtpSecurity: ConnectionSecurity
    /**
     * the IMAP login, placeholders resolved
     */
    public var username: String
    /**
     * the SMTP login; equal to `username` except where the source names another (iCloud: local part for IMAP, full address for SMTP)
     */
    public var smtpUsername: String
    public var authMethod: AuthMethod
    public var source: DetectionSource

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(imapHost: String, imapPort: UInt16, imapSecurity: ConnectionSecurity, smtpHost: String, smtpPort: UInt16, smtpSecurity: ConnectionSecurity, 
        /**
         * the IMAP login, placeholders resolved
         */username: String, 
        /**
         * the SMTP login; equal to `username` except where the source names another (iCloud: local part for IMAP, full address for SMTP)
         */smtpUsername: String, authMethod: AuthMethod, source: DetectionSource) {
        self.imapHost = imapHost
        self.imapPort = imapPort
        self.imapSecurity = imapSecurity
        self.smtpHost = smtpHost
        self.smtpPort = smtpPort
        self.smtpSecurity = smtpSecurity
        self.username = username
        self.smtpUsername = smtpUsername
        self.authMethod = authMethod
        self.source = source
    }
}

