extension AccountConfig: Sendable {}
#endif


extension AccountConfig: Equatable, Hashable {
    public static func ==(lhs: AccountConfig, rhs: AccountConfig) -> Bool {
        if lhs.imapHost != rhs.imapHost {
            return false
        }
        if lhs.imapPort != rhs.imapPort {
            return false
        }
        if lhs.imapSecurity != rhs.imapSecurity {
            return false
        }
        if lhs.smtpHost != rhs.smtpHost {
            return false
        }
        if lhs.smtpPort != rhs.smtpPort {
            return false
        }
        if lhs.smtpSecurity != rhs.smtpSecurity {
            return false
        }
        if lhs.username != rhs.username {
            return false
        }
        if lhs.smtpUsername != rhs.smtpUsername {
            return false
        }
        if lhs.authMethod != rhs.authMethod {
            return false
        }
        if lhs.source != rhs.source {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(imapHost)
        hasher.combine(imapPort)
        hasher.combine(imapSecurity)
        hasher.combine(smtpHost)
        hasher.combine(smtpPort)
        hasher.combine(smtpSecurity)
        hasher.combine(username)
        hasher.combine(smtpUsername)
        hasher.combine(authMethod)
        hasher.combine(source)
    }
}



