extension ActionFailed: Sendable {}
#endif


extension ActionFailed: Equatable, Hashable {
    public static func ==(lhs: ActionFailed, rhs: ActionFailed) -> Bool {
        if lhs.accountName != rhs.accountName {
            return false
        }
        if lhs.reasonWords != rhs.reasonWords {
            return false
        }
        if lhs.retryable != rhs.retryable {
            return false
        }
        if lhs.code != rhs.code {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(accountName)
        hasher.combine(reasonWords)
        hasher.combine(retryable)
        hasher.combine(code)
    }
}



