public struct DetectionResult {
    public var outcome: DetectionOutcome
    /**
     * The last step that ran; None when the address was refused before any step.
     */
    public var stepReached: DetectionStep?
    /**
     * Every step that ran, in order.
     */
    public var progress: [DetectionProgress]
    /**
     * Autodiscover named the domain a Microsoft 365 tenant (J4.3).
     */
    public var microsoft365Tenant: Bool
    /**
     * "Sign in with Google: coming soon" when the provider is OAuth2-only; None otherwise.
     */
    public var signInComingSoon: String?
    /**
     * The provider the address belongs to, when detection knows it (delta 14; core-autoconfig r2 fills it from the
     * configuration's host by its provider table). None = a plain IMAP host. The default keeps Swift callers compiling.
     */
    public var provider: DetectedProvider?
    /**
     * The provider signs in by OAuth2 only for this address, so Add account asks for the person's own client ID
     * (`SetOAuthClient`) and opens the sign-in (`StartOAuthSignIn`) instead of a password (delta 14).
     */
    public var signInNeeded: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(outcome: DetectionOutcome, 
        /**
         * The last step that ran; None when the address was refused before any step.
         */stepReached: DetectionStep?, 
        /**
         * Every step that ran, in order.
         */progress: [DetectionProgress], 
        /**
         * Autodiscover named the domain a Microsoft 365 tenant (J4.3).
         */microsoft365Tenant: Bool, 
        /**
         * "Sign in with Google: coming soon" when the provider is OAuth2-only; None otherwise.
         */signInComingSoon: String?, 
        /**
         * The provider the address belongs to, when detection knows it (delta 14; core-autoconfig r2 fills it from the
         * configuration's host by its provider table). None = a plain IMAP host. The default keeps Swift callers compiling.
         */provider: DetectedProvider? = nil, 
        /**
         * The provider signs in by OAuth2 only for this address, so Add account asks for the person's own client ID
         * (`SetOAuthClient`) and opens the sign-in (`StartOAuthSignIn`) instead of a password (delta 14).
         */signInNeeded: Bool = false) {
        self.outcome = outcome
        self.stepReached = stepReached
        self.progress = progress
        self.microsoft365Tenant = microsoft365Tenant
        self.signInComingSoon = signInComingSoon
        self.provider = provider
        self.signInNeeded = signInNeeded
    }
}

#if compiler(>=6)
extension DetectionResult: Sendable {}
#endif


extension DetectionResult: Equatable, Hashable {
    public static func ==(lhs: DetectionResult, rhs: DetectionResult) -> Bool {
        if lhs.outcome != rhs.outcome {
            return false
        }
        if lhs.stepReached != rhs.stepReached {
            return false
        }
        if lhs.progress != rhs.progress {
            return false
        }
        if lhs.microsoft365Tenant != rhs.microsoft365Tenant {
            return false
        }
        if lhs.signInComingSoon != rhs.signInComingSoon {
            return false
        }
        if lhs.provider != rhs.provider {
            return false
        }
        if lhs.signInNeeded != rhs.signInNeeded {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(outcome)
        hasher.combine(stepReached)
        hasher.combine(progress)
        hasher.combine(microsoft365Tenant)
        hasher.combine(signInComingSoon)
        hasher.combine(provider)
        hasher.combine(signInNeeded)
    }
}



