         */refusal: ImportRefusal?) {
        self.runId = runId
        self.sourceId = sourceId
        self.state = state
        self.done = done
        self.total = total
        self.current = current
        self.stored = stored
        self.skipped = skipped
        self.refusal = refusal
    }
}

