/**
 * Which view of the inbox a list shows.
 */
public struct InboxQuery {
    public var tabId: String
    /**
     * None = every included account
     */
    public var accountId: String?
    public var labelId: String?
    /**
     * which mailbox the list shows; None (the default) is the inbox with its tabs, Some ignores `tab_id` (delta 9)
     */
    public var mailbox: Mailbox?
    /**
     * the accounts the list shows, as a SET (delta 10): empty = every account, else exactly these. Canonical; the older
     * `account_id` is read only when this is empty (`query_accounts`).
     */
    public var accountIds: [String]
    /**
     * filters on the current list, all of which a row must pass (delta 10, ⇧U ⇧S ⇧I ⇧R)
     */
    public var filters: [InboxFilter]
    /**
     * a saved search (delta 14): Some lists exactly what that smart folder's saved words find, newest first, and ignores
     * `tab_id`, `mailbox` and the labels; the account set and the filters still apply. Its count is the unread rows of the
     * same query, so the sidebar's figure and the list cannot disagree.
     */
    public var smartFolderId: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(tabId: String, 
        /**
         * None = every included account
         */accountId: String?, labelId: String?, 
        /**
         * which mailbox the list shows; None (the default) is the inbox with its tabs, Some ignores `tab_id` (delta 9)
         */mailbox: Mailbox? = nil, 
        /**
         * the accounts the list shows, as a SET (delta 10): empty = every account, else exactly these. Canonical; the older
         * `account_id` is read only when this is empty (`query_accounts`).
         */accountIds: [String] = [], 
        /**
         * filters on the current list, all of which a row must pass (delta 10, ⇧U ⇧S ⇧I ⇧R)
         */filters: [InboxFilter] = [], 
        /**
         * a saved search (delta 14): Some lists exactly what that smart folder's saved words find, newest first, and ignores
         * `tab_id`, `mailbox` and the labels; the account set and the filters still apply. Its count is the unread rows of the
         * same query, so the sidebar's figure and the list cannot disagree.
         */smartFolderId: String? = nil) {
        self.tabId = tabId
        self.accountId = accountId
        self.labelId = labelId
        self.mailbox = mailbox
        self.accountIds = accountIds
        self.filters = filters
        self.smartFolderId = smartFolderId
    }
}

#if compiler(>=6)
extension InboxQuery: Sendable {}
#endif


extension InboxQuery: Equatable, Hashable {
    public static func ==(lhs: InboxQuery, rhs: InboxQuery) -> Bool {
        if lhs.tabId != rhs.tabId {
            return false
        }
        if lhs.accountId != rhs.accountId {
            return false
        }
        if lhs.labelId != rhs.labelId {
            return false
        }
        if lhs.mailbox != rhs.mailbox {
            return false
        }
        if lhs.accountIds != rhs.accountIds {
            return false
        }
        if lhs.filters != rhs.filters {
            return false
        }
        if lhs.smartFolderId != rhs.smartFolderId {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(tabId)
        hasher.combine(accountId)
        hasher.combine(labelId)
        hasher.combine(mailbox)
        hasher.combine(accountIds)
        hasher.combine(filters)
        hasher.combine(smartFolderId)
    }
}



