        /**
         * what the label means, in the owner's words; the decision model reads it
         */description: String, scope: LabelScope, rules: RuleSet, pinned: Bool) {
        self.name = name
        self.parentId = parentId
        self.colour = colour
        self.description = description
        self.scope = scope
        self.rules = rules
        self.pinned = pinned
    }
}

