#endif


extension MessageBody: Equatable, Hashable {
    public static func ==(lhs: MessageBody, rhs: MessageBody) -> Bool {
        if lhs.messageId != rhs.messageId {
            return false
        }
        if lhs.safeHtml != rhs.safeHtml {
            return false
        }
        if lhs.plainText != rhs.plainText {
            return false
