        if lhs.picturesBlocked != rhs.picturesBlocked {
            return false
        }
        if lhs.pixelTrackers != rhs.pixelTrackers {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(messageId)
        hasher.combine(safeHtml)
        hasher.combine(plainText)
        hasher.combine(trackersBlocked)
        hasher.combine(quoteOffset)
        hasher.combine(quotedRanges)
        hasher.combine(segments)
        hasher.combine(foldFrom)
        hasher.combine(layout)
        hasher.combine(layoutReasons)
        hasher.combine(displayHtml)
        hasher.combine(writtenHtml)
        hasher.combine(bodyWarnings)
        hasher.combine(picturesBlocked)
        hasher.combine(pixelTrackers)
    }
}



