/**
 * What a rule can read of one message.
 */
public struct MessageFacts {
    public var messageId: String
    public var accountId: String
    public var fromName: String
    public var fromAddress: String
    public var to: [String]
    public var cc: [String]
    public var subject: String
    public var body: String
    public var hasAttachment: Bool
    /**
     * the List-Id / List-Unsubscribe header words; "" = none
     */
    public var listHeader: String
    public var unread: Bool
    public var receivedAtMs: Int64
    /**
     * delta 17, the facts of the grid beyond unread / attachment / list. Required in Rust (a caller that forgets one is a compile error,
     * not a silent "no"); UniFFI defaults keep Swift callers written before compiling. The mailing-list fact is `list_header` non-empty.
     * an inbound message the owner has not answered (the waiting definition)
     */
    public var unanswered: Bool
    public var starred: Bool
    /**
     * the sender is on the VIP list
     */
    public var vipSender: Bool
    /**
     * the owner is in Cc, not To
     */
    public var ccMe: Bool
    /**
     * the owner replied to this message
     */
    public var repliedByMe: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(messageId: String, accountId: String, fromName: String, fromAddress: String, to: [String], cc: [String], subject: String, body: String, hasAttachment: Bool, 
        /**
         * the List-Id / List-Unsubscribe header words; "" = none
         */listHeader: String, unread: Bool, receivedAtMs: Int64, 
        /**
         * delta 17, the facts of the grid beyond unread / attachment / list. Required in Rust (a caller that forgets one is a compile error,
         * not a silent "no"); UniFFI defaults keep Swift callers written before compiling. The mailing-list fact is `list_header` non-empty.
         * an inbound message the owner has not answered (the waiting definition)
         */unanswered: Bool = false, starred: Bool = false, 
        /**
         * the sender is on the VIP list
         */vipSender: Bool = false, 
        /**
         * the owner is in Cc, not To
         */ccMe: Bool = false, 
        /**
         * the owner replied to this message
         */repliedByMe: Bool = false) {
        self.messageId = messageId
        self.accountId = accountId
        self.fromName = fromName
        self.fromAddress = fromAddress
        self.to = to
        self.cc = cc
        self.subject = subject
        self.body = body
        self.hasAttachment = hasAttachment
        self.listHeader = listHeader
        self.unread = unread
        self.receivedAtMs = receivedAtMs
        self.unanswered = unanswered
        self.starred = starred
        self.vipSender = vipSender
        self.ccMe = ccMe
        self.repliedByMe = repliedByMe
    }
}

