            return false
        }
        if lhs.entry != rhs.entry {
            return false
        }
        if lhs.ai != rhs.ai {
            return false
        }
        if lhs.exit != rhs.exit {
            return false
        }
        if lhs.draftId != rhs.draftId {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
