    public var historyFetched: Bool
    public var messagesIndexed: UInt64
    public var lastError: ActionFailed?
    public var providerStatusWords: String?
    public var lastSyncedMs: Int64?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(accountId: String, historyFetched: Bool, messagesIndexed: UInt64, lastError: ActionFailed?, providerStatusWords: String?, lastSyncedMs: Int64?) {
        self.accountId = accountId
        self.historyFetched = historyFetched
        self.messagesIndexed = messagesIndexed
        self.lastError = lastError
        self.providerStatusWords = providerStatusWords
        self.lastSyncedMs = lastSyncedMs
    }
}

#if compiler(>=6)
extension SyncState: Sendable {}
#endif


extension SyncState: Equatable, Hashable {
    public static func ==(lhs: SyncState, rhs: SyncState) -> Bool {
        if lhs.accountId != rhs.accountId {
            return false
        }
        if lhs.historyFetched != rhs.historyFetched {
            return false
        }
        if lhs.messagesIndexed != rhs.messagesIndexed {
            return false
        }
        if lhs.lastError != rhs.lastError {
            return false
        }
        if lhs.providerStatusWords != rhs.providerStatusWords {
            return false
        }
        if lhs.lastSyncedMs != rhs.lastSyncedMs {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(accountId)
        hasher.combine(historyFetched)
        hasher.combine(messagesIndexed)
        hasher.combine(lastError)
        hasher.combine(providerStatusWords)
        hasher.combine(lastSyncedMs)
    }
}



