/**
 * The outcome of checking a configuration with a real login (J4.2). `ok` and `refused_by` are derived from `steps` by
 * `from_steps`; build the report there and the two cannot disagree with the steps.
 */
public struct ValidationReport {
    public var ok: Bool
    public var steps: [ValidationStep]
    public var roles: [FolderRoleMapping]
    public var folderCount: UInt32
    /**
     * The host that refused, in the failing step's own words; None when every step passed.
     */
    public var refusedBy: String?
    /**
     * One line for the screen: what passed, or which server refused and why. A refusal keeps the server's RAW text here; the
     * sheet shows `cause`'s plain sentence first and this text behind "Details" (SPEC A87).
     */
    public var summaryWords: String
    /**
     * Why the check failed, as one known cause (SPEC A87, 2026-11-09); None when every step passed. Additive: a writer
     * built before A87 leaves it None and the screen falls back to the raw words.
     */
    public var cause: RefusalCause?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(ok: Bool, steps: [ValidationStep], roles: [FolderRoleMapping], folderCount: UInt32, 
        /**
         * The host that refused, in the failing step's own words; None when every step passed.
         */refusedBy: String?, 
        /**
         * One line for the screen: what passed, or which server refused and why. A refusal keeps the server's RAW text here; the
         * sheet shows `cause`'s plain sentence first and this text behind "Details" (SPEC A87).
         */summaryWords: String, 
        /**
         * Why the check failed, as one known cause (SPEC A87, 2026-11-09); None when every step passed. Additive: a writer
         * built before A87 leaves it None and the screen falls back to the raw words.
         */cause: RefusalCause? = nil) {
        self.ok = ok
        self.steps = steps
        self.roles = roles
        self.folderCount = folderCount
        self.refusedBy = refusedBy
        self.summaryWords = summaryWords
        self.cause = cause
    }
}

#if compiler(>=6)
extension ValidationReport: Sendable {}
#endif


extension ValidationReport: Equatable, Hashable {
    public static func ==(lhs: ValidationReport, rhs: ValidationReport) -> Bool {
        if lhs.ok != rhs.ok {
            return false
        }
        if lhs.steps != rhs.steps {
            return false
        }
        if lhs.roles != rhs.roles {
            return false
        }
        if lhs.folderCount != rhs.folderCount {
            return false
        }
        if lhs.refusedBy != rhs.refusedBy {
            return false
        }
        if lhs.summaryWords != rhs.summaryWords {
            return false
        }
        if lhs.cause != rhs.cause {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(ok)
        hasher.combine(steps)
        hasher.combine(roles)
        hasher.combine(folderCount)
        hasher.combine(refusedBy)
        hasher.combine(summaryWords)
        hasher.combine(cause)
    }
}



