    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ValidationReport {
        return
            try ValidationReport(
                ok: FfiConverterBool.read(from: &buf), 
                steps: FfiConverterSequenceTypeValidationStep.read(from: &buf), 
                roles: FfiConverterSequenceTypeFolderRoleMapping.read(from: &buf), 
                folderCount: FfiConverterUInt32.read(from: &buf), 
                refusedBy: FfiConverterOptionString.read(from: &buf), 
