    public static func write(_ value: Command, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .archive(messageIds):
            writeInt(&buf, Int32(1))
            FfiConverterSequenceString.write(messageIds, into: &buf)
            
        
        case let .snooze(messageIds,when):
            writeInt(&buf, Int32(2))
            FfiConverterSequenceString.write(messageIds, into: &buf)
            FfiConverterTypeSnoozeWhen.write(when, into: &buf)
            
        
        case let .pin(messageId,pinned):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(messageId, into: &buf)
            FfiConverterBool.write(pinned, into: &buf)
            
        
        case let .label(messageIds,labelName,createIfMissing):
            writeInt(&buf, Int32(4))
            FfiConverterSequenceString.write(messageIds, into: &buf)
            FfiConverterString.write(labelName, into: &buf)
            FfiConverterBool.write(createIfMissing, into: &buf)
            
        
        case let .moveToAccount(messageIds,accountId):
            writeInt(&buf, Int32(5))
            FfiConverterSequenceString.write(messageIds, into: &buf)
            FfiConverterString.write(accountId, into: &buf)
            
        
        case .undo:
            writeInt(&buf, Int32(6))
        
        
        case let .markRead(messageIds,read):
            writeInt(&buf, Int32(7))
            FfiConverterSequenceString.write(messageIds, into: &buf)
            FfiConverterBool.write(read, into: &buf)
            
        
        case let .openThread(threadId):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(threadId, into: &buf)
            
        
        case let .quickSend(threadId,body):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(threadId, into: &buf)
            FfiConverterString.write(body, into: &buf)
            
        
        case let .send(draftId):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(draftId, into: &buf)
            
        
        case let .cancelSend(outboxId):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(outboxId, into: &buf)
            
        
        case let .schedule(draftId,atMs):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(draftId, into: &buf)
            FfiConverterInt64.write(atMs, into: &buf)
            
        
        case let .search(query):
            writeInt(&buf, Int32(13))
            FfiConverterString.write(query, into: &buf)
            
        
        case let .saveSmartFolder(name,ruleWords):
            writeInt(&buf, Int32(14))
            FfiConverterString.write(name, into: &buf)
            FfiConverterString.write(ruleWords, into: &buf)
            
        
        case let .addAccount(address,provider):
            writeInt(&buf, Int32(15))
            FfiConverterString.write(address, into: &buf)
            FfiConverterTypeMailProvider.write(provider, into: &buf)
            
        
        case let .ask(agentId,question):
            writeInt(&buf, Int32(16))
            FfiConverterOptionString.write(agentId, into: &buf)
            FfiConverterString.write(question, into: &buf)
            
        
        case let .approveProposal(proposalId,approve):
            writeInt(&buf, Int32(17))
            FfiConverterString.write(proposalId, into: &buf)
            FfiConverterBool.write(approve, into: &buf)
            
        
        case let .renameSplitTab(tabId,name):
            writeInt(&buf, Int32(18))
            FfiConverterString.write(tabId, into: &buf)
            FfiConverterString.write(name, into: &buf)
            
        
        case let .renameLabel(labelId,name):
            writeInt(&buf, Int32(19))
            FfiConverterString.write(labelId, into: &buf)
            FfiConverterString.write(name, into: &buf)
            
        
        case let .moveLabel(labelId,parentId):
            writeInt(&buf, Int32(20))
            FfiConverterString.write(labelId, into: &buf)
            FfiConverterOptionString.write(parentId, into: &buf)
            
        
        case let .createLabel(name,parentId):
            writeInt(&buf, Int32(21))
            FfiConverterString.write(name, into: &buf)
            FfiConverterOptionString.write(parentId, into: &buf)
            
        
        case let .deleteMessage(messageId):
            writeInt(&buf, Int32(22))
            FfiConverterString.write(messageId, into: &buf)
            
        
        case let .mergeContacts(keepId,mergeId):
            writeInt(&buf, Int32(23))
            FfiConverterString.write(keepId, into: &buf)
            FfiConverterString.write(mergeId, into: &buf)
            
        
        case let .giveAgentConsent(providerId):
            writeInt(&buf, Int32(24))
            FfiConverterString.write(providerId, into: &buf)
            
        
        case let .setNotchSetting(setting):
            writeInt(&buf, Int32(25))
            FfiConverterTypeNotchSetting.write(setting, into: &buf)
            
        
        case let .setNotchAlerts(alerts):
            writeInt(&buf, Int32(26))
            FfiConverterTypeNotchAlerts.write(alerts, into: &buf)
            
        
        case let .setNotificationSetting(setting):
