            FfiConverterTypeNotificationSetting.write(setting, into: &buf)
            
        
        case let .setNotification(accountId,enabled):
            writeInt(&buf, Int32(28))
            FfiConverterString.write(accountId, into: &buf)
            FfiConverterBool.write(enabled, into: &buf)
            
        
        case let .setAccountIcon(accountId,source):
            writeInt(&buf, Int32(29))
            FfiConverterString.write(accountId, into: &buf)
            FfiConverterTypeAccountIconSource.write(source, into: &buf)
            
        
        case let .setAccountColour(accountId,colour):
            writeInt(&buf, Int32(30))
            FfiConverterString.write(accountId, into: &buf)
            FfiConverterString.write(colour, into: &buf)
            
        
        case let .saveProviderKey(providerId,key):
            writeInt(&buf, Int32(31))
            FfiConverterString.write(providerId, into: &buf)
            FfiConverterTypeSecretText.write(key, into: &buf)
            
        
        case let .removeProviderKey(providerId):
            writeInt(&buf, Int32(32))
            FfiConverterString.write(providerId, into: &buf)
            
        
        case let .saveAgentConfig(config):
            writeInt(&buf, Int32(33))
            FfiConverterTypeAgentConfig.write(config, into: &buf)
            
        
        case let .saveDecisionModel(model):
            writeInt(&buf, Int32(34))
            FfiConverterTypeDecisionModel.write(model, into: &buf)
            
        
        case let .chooseSpeechEngine(kind):
            writeInt(&buf, Int32(35))
            FfiConverterTypeSpeechEngineKind.write(kind, into: &buf)
            
        
        case .previewDecisions:
            writeInt(&buf, Int32(36))
        
        
        case let .previewDecisionList(pageId,entries):
            writeInt(&buf, Int32(37))
            FfiConverterString.write(pageId, into: &buf)
            FfiConverterSequenceTypePreviewEntry.write(entries, into: &buf)
            
        
        case .applyDecisionPreview:
            writeInt(&buf, Int32(38))
        
        
        case let .saveDecisionList(pageId,nodeIds,rules):
            writeInt(&buf, Int32(39))
            FfiConverterString.write(pageId, into: &buf)
            FfiConverterSequenceString.write(nodeIds, into: &buf)
            FfiConverterSequenceTypeRuleSet.write(rules, into: &buf)
            
        
        case let .setMcpGrant(appName,allowed):
            writeInt(&buf, Int32(40))
            FfiConverterString.write(appName, into: &buf)
            FfiConverterBool.write(allowed, into: &buf)
            
        
        case let .setMcpServer(on):
