// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * The wire security of one server: implicit TLS, or STARTTLS upgrade.
 */

public enum ConnectionSecurity {
    
    case ssl
    case starttls
}


#if compiler(>=6)
extension ConnectionSecurity: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeConnectionSecurity: FfiConverterRustBuffer {
    typealias SwiftType = ConnectionSecurity

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ConnectionSecurity {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .ssl
        
        case 2: return .starttls
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ConnectionSecurity, into buf: inout [UInt8]) {
        switch value {
        
        
        case .ssl:
            writeInt(&buf, Int32(1))
        
        
        case .starttls:
            writeInt(&buf, Int32(2))
        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeConnectionSecurity_lift(_ buf: RustBuffer) throws -> ConnectionSecurity {
    return try FfiConverterTypeConnectionSecurity.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeConnectionSecurity_lower(_ value: ConnectionSecurity) -> RustBuffer {
    return FfiConverterTypeConnectionSecurity.lower(value)
}


extension ConnectionSecurity: Equatable, Hashable {}







public enum CoreError: Swift.Error {

    
    
    /**
     * An action the owner asked for did not happen.
     */
    case Action(failure: ActionFailed
    )
    /**
     * The input crossed a boundary in a shape the contract refuses (parse, don't cast).
     */
    case Invalid(field: String, reasonWords: String
    )
    /**
     * The thing named does not exist.
     */
    case NotFound(kind: String, id: String
    )
    /**
     * A Swift implementation of a foreign trait threw something the contract does not name.
     */
    case Unexpected(reasonWords: String
    )
    /**
     * A provider asked us to slow down (added 2026-11-07, sync engine): `provider` names it in words
     * ("Gmail", "Microsoft 365"); `retry_after_ms` is its own wait when it named one.
     */
    case Throttled(provider: String, retryAfterMs: UInt64?
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Action(
            failure: try FfiConverterTypeActionFailed.read(from: &buf)
            )
        case 2: return .Invalid(
            field: try FfiConverterString.read(from: &buf), 
            reasonWords: try FfiConverterString.read(from: &buf)
            )
        case 3: return .NotFound(
            kind: try FfiConverterString.read(from: &buf), 
            id: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Unexpected(
            reasonWords: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Throttled(
            provider: try FfiConverterString.read(from: &buf), 
            retryAfterMs: try FfiConverterOptionUInt64.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Action(failure):
            writeInt(&buf, Int32(1))
            FfiConverterTypeActionFailed.write(failure, into: &buf)
            
        
        case let .Invalid(field,reasonWords):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(field, into: &buf)
            FfiConverterString.write(reasonWords, into: &buf)
            
        
        case let .NotFound(kind,id):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(kind, into: &buf)
            FfiConverterString.write(id, into: &buf)
            
        
        case let .Unexpected(reasonWords):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reasonWords, into: &buf)
            
        
        case let .Throttled(provider,retryAfterMs):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(provider, into: &buf)
            FfiConverterOptionUInt64.write(retryAfterMs, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreError_lift(_ buf: RustBuffer) throws -> CoreError {
    return try FfiConverterTypeCoreError.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreError_lower(_ value: CoreError) -> RustBuffer {
    return FfiConverterTypeCoreError.lower(value)
}


extension CoreError: Equatable, Hashable {}




extension CoreError: Foundation.LocalizedError {
    public var errorDescription: String? {
        String(reflecting: self)
    }
}




