        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .rule(ruleId: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .laya
        
        case 3: return .jev
        
        case 4: return .owner
        
        case 5: return .`default`
        
        case 6: return .apple
        
        case 7: return .model(model: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DecidedBy, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .rule(ruleId):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(ruleId, into: &buf)
            
        
        case .laya:
            writeInt(&buf, Int32(2))
        
        
        case .jev:
            writeInt(&buf, Int32(3))
        
        
        case .owner:
            writeInt(&buf, Int32(4))
        
        
        case .`default`:
            writeInt(&buf, Int32(5))
        
        
        case .apple:
            writeInt(&buf, Int32(6))
        
        
        case let .model(model):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(model, into: &buf)
            
        }
    }
}


