        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .found(config: try FfiConverterTypeAccountConfig.read(from: &buf)
        )
        
        case 2: return .imapOnly(imapHost: try FfiConverterString.read(from: &buf), imapPort: try FfiConverterUInt16.read(from: &buf), imapSecurity: try FfiConverterTypeConnectionSecurity.read(from: &buf), username: try FfiConverterString.read(from: &buf), source: try FfiConverterTypeDetectionSource.read(from: &buf)
        )
        
        case 3: return .refused(words: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DetectionOutcome, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .found(config):
            writeInt(&buf, Int32(1))
            FfiConverterTypeAccountConfig.write(config, into: &buf)
            
        
        case let .imapOnly(imapHost,imapPort,imapSecurity,username,source):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(imapHost, into: &buf)
            FfiConverterUInt16.write(imapPort, into: &buf)
            FfiConverterTypeConnectionSecurity.write(imapSecurity, into: &buf)
            FfiConverterString.write(username, into: &buf)
            FfiConverterTypeDetectionSource.write(source, into: &buf)
            
        
        case let .refused(words):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(words, into: &buf)
            
        }
    }
