        )
        
        case 2: return .attachmentName
        
        case 3: return .attachmentContent
        
        case 4: return .meaningOnly
        
        case 5: return .senderWords(nameRanges: try FfiConverterSequenceTypeTextRange.read(from: &buf), addressRanges: try FfiConverterSequenceTypeTextRange.read(from: &buf)
        )
        
        case 6: return .textWords(ranges: try FfiConverterSequenceTypeTextRange.read(from: &buf)
        )
        
        case 7: return .related
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MatchedIn, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .subjectWords(ranges):
            writeInt(&buf, Int32(1))
            FfiConverterSequenceTypeTextRange.write(ranges, into: &buf)
            
        
        case .attachmentName:
            writeInt(&buf, Int32(2))
        
        
        case .attachmentContent:
            writeInt(&buf, Int32(3))
        
        
        case .meaningOnly:
            writeInt(&buf, Int32(4))
        
        
        case let .senderWords(nameRanges,addressRanges):
