// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Where one outgoing message stands. A Failed entry always carries the words the owner reads.
 */

public enum OutboxState {
    
    case undoable(untilMs: Int64
    )
    case scheduled(atMs: Int64
    )
    case sending
    case sent(atMs: Int64
    )
    case failed(failure: ActionFailed, attempts: UInt32
    )
    case cancelled
    /**
     * A scheduled entry whose time passed OUTBOX_LATE_AFTER_MS ago with no device awake to send it
     * (added 2026-11-07, outbox crate); it still goes out when a device wakes.
     */
    case late(scheduledAtMs: Int64
    )
    /**
     * Due, but there is no network path; it goes when the path comes back (OnlinePort). Not a failure.
     */
    case waitingForNetwork(sinceMs: Int64
    )
}


#if compiler(>=6)
extension OutboxState: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeOutboxState: FfiConverterRustBuffer {
    typealias SwiftType = OutboxState

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> OutboxState {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .undoable(untilMs: try FfiConverterInt64.read(from: &buf)
        )
        
        case 2: return .scheduled(atMs: try FfiConverterInt64.read(from: &buf)
        )
        
        case 3: return .sending
        
        case 4: return .sent(atMs: try FfiConverterInt64.read(from: &buf)
        )
        
        case 5: return .failed(failure: try FfiConverterTypeActionFailed.read(from: &buf), attempts: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 6: return .cancelled
        
        case 7: return .late(scheduledAtMs: try FfiConverterInt64.read(from: &buf)
        )
        
        case 8: return .waitingForNetwork(sinceMs: try FfiConverterInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: OutboxState, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .undoable(untilMs):
            writeInt(&buf, Int32(1))
            FfiConverterInt64.write(untilMs, into: &buf)
            
        
        case let .scheduled(atMs):
            writeInt(&buf, Int32(2))
            FfiConverterInt64.write(atMs, into: &buf)
            
        
        case .sending:
            writeInt(&buf, Int32(3))
        
        
        case let .sent(atMs):
            writeInt(&buf, Int32(4))
            FfiConverterInt64.write(atMs, into: &buf)
            
        
        case let .failed(failure,attempts):
            writeInt(&buf, Int32(5))
            FfiConverterTypeActionFailed.write(failure, into: &buf)
            FfiConverterUInt32.write(attempts, into: &buf)
            
        
        case .cancelled:
            writeInt(&buf, Int32(6))
        
        
        case let .late(scheduledAtMs):
            writeInt(&buf, Int32(7))
            FfiConverterInt64.write(scheduledAtMs, into: &buf)
            
        
        case let .waitingForNetwork(sinceMs):
            writeInt(&buf, Int32(8))
            FfiConverterInt64.write(sinceMs, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeOutboxState_lift(_ buf: RustBuffer) throws -> OutboxState {
    return try FfiConverterTypeOutboxState.lift(buf)
}

