 * with the SNOOZE_* constants of docs/CONSTANTS.md.
 */

public enum SnoozeWhen {
    
    case laterToday
    case tomorrowMorning
    case nextWeek
    case at(atMs: Int64
    )
}


#if compiler(>=6)
extension SnoozeWhen: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSnoozeWhen: FfiConverterRustBuffer {
    typealias SwiftType = SnoozeWhen

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SnoozeWhen {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .laterToday
        
        case 2: return .tomorrowMorning
        
        case 3: return .nextWeek
        
        case 4: return .at(atMs: try FfiConverterInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SnoozeWhen, into buf: inout [UInt8]) {
        switch value {
        
        
        case .laterToday:
            writeInt(&buf, Int32(1))
        
        
        case .tomorrowMorning:
            writeInt(&buf, Int32(2))
        
        
        case .nextWeek:
            writeInt(&buf, Int32(3))
        
        
        case let .at(atMs):
            writeInt(&buf, Int32(4))
            FfiConverterInt64.write(atMs, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSnoozeWhen_lift(_ buf: RustBuffer) throws -> SnoozeWhen {
