/**
 * The sentence for an account removal, once: the counts that are not zero, then the sign-in, then the server line.
 */
public func accountRemovalWords(accountName: String, messages: UInt32, drafts: UInt32, outbox: UInt32, labels: UInt32) -> String  {
    return try!  FfiConverterString.lift(try! rustCall() {
    uniffi_contracts_fn_func_account_removal_words(
        FfiConverterString.lower(accountName),
        FfiConverterUInt32.lower(messages),
        FfiConverterUInt32.lower(drafts),
        FfiConverterUInt32.lower(outbox),
        FfiConverterUInt32.lower(labels),$0
    )
})
}
public func aiProviderStateFromKey(key: String) -> AiProviderState?  {
    return try!  FfiConverterOptionTypeAiProviderState.lift(try! rustCall() {
    uniffi_contracts_fn_func_ai_provider_state_from_key(
        FfiConverterString.lower(key),$0
    )
})
}
public func aiProviderStateKey(s: AiProviderState) -> String  {
    return try!  FfiConverterString.lift(try! rustCall() {
    uniffi_contracts_fn_func_ai_provider_state_key(
        FfiConverterTypeAiProviderState_lower(s),$0
    )
})
